        ("VKB-021", "pomegranate_price", "ದಾಳಿಂಬೆ ಕೆಜಿ ಅಥವಾ ಬಾಕ್ಸ್ ದರ ಎಷ್ಟಿದೆ?", "What is pomegranate price?", "General", ["ದಾಳಿಂಬೆ", "ಭಗವಾ", "ಬೆಲೆ", "ಕೆಜಿ", "ಬಾಗಲಕೋಟೆ"], "ಭಗವಾ ತಳಿಯ ಉತ್ತಮ ದಾಳಿಂಬೆ 1 ಕೆಜಿಗೆ ತೋಟದಲ್ಲೇ ₹110 – ₹150 ದರ ಸಿಗುತ್ತಿದೆ. ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ಗ್ರೇಡ್-1 ಹಣ್ಣಿಗೆ ₹160 – ₹190 ಬೆಲೆಯಿದೆ."),
        ("VKB-022", "grapes_price", "ದ್ರಾಕ್ಷಿ (ಥಾಮ್ಸನ್ ಸೀಡ್‌ಲೆಸ್, ದಿಲ್‌ಕುಶ್) ಬೆಲೆ ಎಷ್ಟು?", "What is grape price?", "General", ["ದ್ರಾಕ್ಷಿ", "ವಿಜಯಪುರ", "ಬೆಂಗಳೂರು ನೀಲಿ", "ಬೆಲೆ"], "ವಿಜಯಪುರ ಥಾಮ್ಸನ್ ಸೀಡ್‌ಲೆಸ್ ದ್ರಾಕ್ಷಿ 1 ಕೆಜಿಗೆ ₹60 – ₹85 ಹಾಗೂ ಬೆಂಗಳೂರು ಬ್ಲೂ ವೈನ್ ದ್ರಾಕ್ಷಿ ₹35 – ₹45 ದರದಲ್ಲಿದೆ."),
        ("VKB-023", "green_chilli_price", "ಹಸಿ ಮೆಣಸಿನಕಾಯಿ ಕ್ವಿಂಟಾಲ್ ಬೆಲೆ ಎಷ್ಟು?", "What is green chilli price per quintal?", "General", ["ಹಸಿ ಮೆಣಸಿನಕಾಯಿ", "ಹಸಿ ಮೆಣಸು", "ಬೆಲೆ", "ಕ್ವಿಂಟಾಲ್"], "ಬೆಂಗಳೂರು, ಕೋಲಾರ ಮತ್ತು ಬೆಳಗಾವಿ ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ 1 ಕ್ವಿಂಟಾಲ್ ಹಸಿ ಮೆಣಸಿನಕಾಯಿ ₹2,800 – ₹4,200 (ಕೆಜಿಗೆ ಸುಮಾರು ₹28 - ₹42) ದರವಿದೆ."),
        ("VKB-024", "coriander_price", "ಕೊತ್ತಂಬರಿ ಸೊಪ್ಪು ಮತ್ತು ಬೀಜದ ಬೆಲೆ ಎಷ್ಟು?", "What is coriander greens and seeds price?", "General", ["ಕೊತ್ತಂಬರಿ", "ಕೊತ್ತಂಬರಿ ಸೊಪ್ಪು", "ದನಿಯಾ", "ಬೆಲೆ"], "ಕೊತ್ತಂಬರಿ ಸೊಪ್ಪು 100 ಕಟ್ಟುಗಳಿಗೆ ₹600 – ₹1,200 ದರವಿದೆ. ಒಣ ದನಿಯಾ ಬೀಜ 1 ಕ್ವಿಂಟಾಲ್‌ಗೆ ₹7,500 – ₹9,200 ದರದಲ್ಲಿದೆ."),
        ("VKB-025", "flowers_price", "ಮಲ್ಲಿಗೆ ಮತ್ತು ಸೇವಂತಿಗೆ ಹೂವಿನ ಮಾರುಕಟ್ಟೆ ದರ ಎಷ್ಟು?", "What is jasmine and chrysanthemum flower price?", "General", ["ಹೂವು", "ಮಲ್ಲಿಗೆ", "ಸೇವಂತಿಗೆ", "ಕೆಆರ್ ಮಾರುಕಟ್ಟೆ", "ಬೆಲೆ"], "ಬೆಂಗಳೂರು ಕೆ.ಆರ್. ಮಾರುಕಟ್ಟೆಯಲ್ಲಿ ಮೈಸೂರು ಮಲ್ಲಿಗೆ 1 ಕೆಜಿಗೆ ₹400 – ₹700 (ಹಬ್ಬದ ದಿನಗಳಲ್ಲಿ ₹1,200 ವರೆಗೆ) ಹಾಗೂ ಸೇವಂತಿಗೆ ₹100 – ₹180 ದರದಲ್ಲಿದೆ.")
