    fertilizer_qas = [
        ("VKB-026", "urea_timing", "ಯೂರಿಯಾ ಗೊಬ್ಬರವನ್ನು ಯಾವಾಗ ಹಾಕಬೇಕು?", ["ಯೂರಿಯಾ", "ಗೊಬ್ಬರ", "ಸಾರಜನಕ", "ಮೇಲುಗೊಬ್ಬರ"], "ಯೂರಿಯಾವನ್ನು ಒಂದೇ ಬಾರಿಗೆ ಹಾಕಬಾರದು. ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ 50% ಮತ್ತು ಬೆಳೆಯು ಕಳೆ ತೆಗೆದ ನಂತರ (25-30 ದಿನಗಳಲ್ಲಿ) ಉಳಿದ 50% ಮೇಲುಗೊಬ್ಬರವಾಗಿ ನೀಡಬೇಕು. ಮಣ್ಣಿನಲ್ಲಿ ತೇವಾಂಶವಿರುವಾಗ ಸಂಜೆ ಹೊತ್ತು ಹಾಕಿದರೆ ಸಾರಜನಕ ನಷ್ಟವಾಗುವುದಿಲ್ಲ. 1 ಎಕರೆಗೆ ಬೆಳೆಯ ಪ್ರಕಾರ 35 ರಿಂದ 50 ಕೆಜಿ ಯೂರಿಯಾ ಸಾಕಾಗುತ್ತದೆ."),
        ("VKB-027", "dap_selection", "ಡಿಎಪಿ (DAP) ಅಥವಾ 20:20:0:13 ಅಥವಾ 10:26:26 ಯಾವುದು ಉತ್ತಮ?", ["ಡಿಎಪಿ", "DAP", "20:20:0:13", "10:26:26"], "ಡಿಎಪಿಯಲ್ಲಿ (18:46:0) ಪೊಟ್ಯಾಷ್ ಇರುವುದಿಲ್ಲ. ಎಣ್ಣೆಕಾಳು ಬೆಳೆಗಳಿಗೆ (ಶೇಂಗಾ, ಸೂರ್ಯಕಾಂತಿ) ಸಲ್ಫರ್ ಇರುವ 20:20:0:13 ಉತ್ತಮ. ಧಾನ್ಯ ಹಾಗೂ ತರಕಾರಿ ಬೆಳೆಗಳಿಗೆ ಪೊಟ್ಯಾಷ್ ಹೆಚ್ಚಿರುವ 10:26:26 ಅಥವಾ 17:17:17 ಸಂಕೀರ್ಣ ಗೊಬ್ಬರಗಳು ಕಾಯಿ ಕಟ್ಟಲು ಮತ್ತು ಇಳುವರಿ ಹೆಚ್ಚಿಸಲು ಅತ್ಯುತ್ತಮ."),
        ("VKB-028", "nano_urea", "ನ್ಯಾನೋ ಯೂರಿಯಾ ಸಿಂಪಡಣೆ ಹೇಗೆ ಮಾಡಬೇಕು?", ["ನ್ಯಾನೋ ಯೂರಿಯಾ", "ಇಫ್ಕೋ", "ಸಿಂಪಡಣೆ", "ಪ್ರಮಾಣ"], "1 ಲೀಟರ್ ನೀರಿಗೆ 4 ಮಿ.ಲೀ ನ್ಯಾನೋ ಯೂರಿಯಾ (16 ಲೀಟರ್ ಪಂಪ್‌ಗೆ 60-65 ಮಿ.ಲೀ) ಬೆರೆಸಿ ಎಲೆಗಳ ಮೇಲೆ ಸಿಂಪಡಿಸಬೇಕು. ಮೊದಲ ಸಿಂಪಡಣೆಯನ್ನು ಬೆಳೆ ಮೊಳಕೆಯೊಡೆದ 30-35 ದಿನಗಳಿಗೆ ಹಾಗೂ ಎರಡನೇ ಸಿಂಪಡಣೆಯನ್ನು ಹೂವಾಡುವ ಮುಂಚೆ ಮಾಡಬೇಕು."),
        ("VKB-029", "potash_importance", "ಪೊಟ್ಯಾಷ್ (MOP) ಗೊಬ್ಬರ ಯಾಕೆ ಹಾಕಬೇಕು?", ["ಪೊಟ್ಯಾಷ್", "MOP", "ಕಾಳು ಕಟ್ಟಲು", "ತೂಕ"], "ಪೊಟ್ಯಾಷ್ ಬೆಳೆಗೆ ರೋಗ ನಿರೋಧಕ ಶಕ್ತಿ ನೀಡುತ್ತದೆ, ಬರವನ್ನು ತಡೆದುಕೊಳ್ಳಲು ನೆರವಾಗುತ್ತದೆ, ಹಾಗೂ ಧಾನ್ಯ-ಹಣ್ಣುಗಳ ತೂಕ, ಹೊಳಪು ಮತ್ತು ಸಕ್ಕರೆ ಅಂಶ ಹೆಚ್ಚಿಸುತ್ತದೆ. ಪೊಟ್ಯಾಷ್ ಇಲ್ಲದಿದ್ದರೆ ತೆನೆಗಳಲ್ಲಿ ಜೊಳ್ಳು ಕಾಳುಗಳು ಹೆಚ್ಚಾಗುತ್ತವೆ."),
        ("VKB-030", "zinc_boron", "ಜಿಂಕ್ ಮತ್ತು ಬೋರಾನ್ ಕೊರತೆಗೆ ಪರಿಹಾರವೇನು?", ["ಜಿಂಕ್", "ಬೋರಾನ್", "ಲಘು ಪೋಷಕಾಂಶ", "ಎಲೆ ಹಳದಿ"], "ಜಿಂಕ್ ಕೊರತೆಯಿಂದ ಎಳೆಯ ಎಲೆಗಳು ಹಳದಿಯಾಗಿ ಬಿಳಿಯಾಗುತ್ತವೆ. ಪರಿಹಾರ: 1 ಎಕರೆಗೆ 10 ಕೆಜಿ ಜಿಂಕ್ ಸಲ್ಫೇಟ್ ಮಣ್ಣಿಗೆ ಹಾಕಿ ಅಥವಾ 2 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ. ಬೋರಾನ್ ಕೊರತೆಯಿಂದ ಹೂವುಗಳು ಉದುರುತ್ತವೆ; ಇದಕ್ಕೆ ಬೋರಾಕ್ಸ್ 1 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-031", "jeevamrutha", "ಜೀವಾಮೃತ ತಯಾರಿಸುವ ವಿಧಾನ ಏನು?", ["ಜೀವಾಮೃತ", "ಸಾವಯವ", "ಸೆಗಣಿ", "ಗೋಮೂತ್ರ"], "200 ಲೀಟರ್ ಡ್ರಮ್‌ನಲ್ಲಿ: 10 ಕೆಜಿ ದೇಸಿ ಹಸುವಿನ ಸೆಗಣಿ + 10 ಲೀಟರ್ ಗೋಮೂತ್ರ + 2 ಕೆಜಿ ಬೆಲ್ಲ + 2 ಕೆಜಿ ದ್ವಿದಳ ಧಾನ್ಯದ ಹಿಟ್ಟು (ಕಡಲೆ/ಹುರುಳಿ) + 1 ಹಿಡಿ ಕಾಡಿನ ಅಥವಾ ಬದುವಿನ ಮಣ್ಣು ಬೆರೆಸಿ 48-72 ಗಂಟೆ ನೆರಳಿನಲ್ಲಿ ಹುದುಗಿಸಿ. ದಿನಕ್ಕೆ 2 ಬಾರಿ ಕೋಲಿನಿಂದ ಬಲಕ್ಕೆ ತಿರುಗಿಸಿ. 1 ಎಕರೆ ಬೆಳೆಗೆ ಹನಿ ನೀರಾವರಿ ಮೂಲಕ ಅಥವಾ ಮಣ್ಣಿಗೆ ಉಣಿಸಿ."),
        ("VKB-032", "panchagavya", "ಪಂಚಗವ್ಯ ಸಿಂಪಡಣೆ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ಪಂಚಗವ್ಯ", "ಹಸುವಿನ ತುಪ್ಪ", "ಹಾಲು", "ಮೊಸರು"], "ಸೆಗಣಿ 5 ಕೆಜಿ + ತುಪ್ಪ 500 ಗ್ರಾಂ ಬೆರೆಸಿ 3 ದಿನ ಇಡಿ. 4ನೇ ದಿನ ಗೋಮೂತ್ರ 3 ಲೀ, ಹಾಲು 2 ಲೀ, ಮೊಸರು 2 ಲೀ, ಎಳನೀರು 3 ಲೀ, ಬೆಲ್ಲ 1 ಕೆಜಿ ಮತ್ತು 12 ಬಾಳೆಹಣ್ಣು ಸೇರಿಸಿ 15 ದಿನ ಹುದುಗಿಸಿ. ಸಿಂಪಡಣೆಗೆ: 1 ಲೀಟರ್ ನೀರಿಗೆ 30 ಮಿ.ಲೀ (3% ದ್ರಾವಣ) ಬೆರೆಸಿ ಸಿಂಪಡಿಸಿ."),
        ("VKB-033", "vermicompost", "ಎರೆಹುಳು ಗೊಬ್ಬರ ಎಕರೆಗೆ ಎಷ್ಟು ಹಾಕಬೇಕು?", ["ಎರೆಹುಳು ಗೊಬ್ಬರ", "ವರ್ಮಿಕಾಂಪೋಸ್ಟ್", "ಪ್ರಮಾಣ"], "ಸಾಮಾನ್ಯ ಬೆಳೆಗಳಿಗೆ 1 ಎಕರೆಗೆ 1 ರಿಂದ 1.5 ಟನ್ ಎರೆಹುಳು ಗೊಬ್ಬರ ಸಾಕಾಗುತ್ತದೆ. ತರಕಾರಿ ಮತ್ತು ಹೂವಿನ ಬೆಳೆಗಳಿಗೆ 2 ಟನ್ ಹಾಕಬಹುದು. ಅಡಿಕೆ ಮತ್ತು ತೆಂಗಿನ ಮರಕ್ಕೆ ವರ್ಷಕ್ಕೆ ಪ್ರತಿ ಮರಕ್ಕೆ 5 ರಿಂದ 8 ಕೆಜಿ ಹಾಕಿ ಬುಡ ಮುಚ್ಚಬೇಕು."),
        ("VKB-034", "neem_cake", "ಬೇವಿನ ಹಿಂಡಿ ಮಣ್ಣಿಗೆ ಹಾಕುವುದರಿಂದ ಏನು ಲಾಭ?", ["ಬೇವಿನ ಹಿಂಡಿ", "ಗೆದ್ದಲು", "ಬೇರು ಹುಳು", "ನೆಮಟೋಡ್"], "ಬೇವಿನ ಹಿಂಡಿಯು ಮಣ್ಣಿನಲ್ಲಿರುವ ಬೇರು ಗಂಟು ಜಂತುಹುಳು (Nematodes) ಮತ್ತು ಗೆದ್ದಲು, ಗೆಣ್ಣು ಹುಳುಗಳನ್ನು ನಾಶಮಾಡುತ್ತದೆ. ಜೊತೆಗೆ ಯೂರಿಯಾದ ಸಾರಜನಕ ಆವಿಯಾಗದಂತೆ ನಿಧಾನವಾಗಿ ಬೆಳೆಗೆ ಸಿಗುವಂತೆ ಮಾಡುತ್ತದೆ. 1 ಎಕರೆಗೆ 100-150 ಕೆಜಿ ಬಳಸಬೇಕು."),
        ("VKB-035", "water_soluble_fert", "19:19:19 ಮತ್ತು 0:52:34 ಗೊಬ್ಬರ ಯಾವಾಗ ಸಿಂಪಡಿಸಬೇಕು?", ["19:19:19", "0:52:34", "0:0:50", "ಡ್ರಿಪ್"], "1. 19:19:19: ಸಸ್ಯದ ಆರಂಭಿಕ ಕವಲೊಡೆಯುವ ಮತ್ತು ಬೆಳವಣಿಗೆ ಹಂತದಲ್ಲಿ (5 ಗ್ರಾಂ/ಲೀ).\n2. 0:52:34: ಹೂ ಮೊಗ್ಗು ಬರುವ ಮತ್ತು ಪರಾಗಸ್ಪರ್ಶ ಹಂತದಲ್ಲಿ (5 ಗ್ರಾಂ/ಲೀ).\n3. 0:0:50: ಕಾಯಿ ಕಟ್ಟಿದ ನಂತರ ತೂಕ, ಬಣ್ಣ ಮತ್ತು ದಪ್ಪ ಬರಲು (5 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ)."),
        ("VKB-036", "soil_test", "ಮಣ್ಣು ಪರೀಕ್ಷೆ ಎಲ್ಲಿ ಮಾಡಿಸುತ್ತಾರೆ?", ["ಮಣ್ಣು ಪರೀಕ್ಷೆ", "ಮಣ್ಣಿನ ಮಾದರಿ", "ರೈತ ಸಂಪರ್ಕ ಕೇಂದ್ರ"], "ಹೊಲದ 8-10 ಕಡೆ V ಆಕಾರದ 9 ಇಂಚು ಗುಂಡಿ ತೆಗೆದು ಮಣ್ಣು ಸಂಗ್ರಹಿಸಿ ಮಿಶ್ರಣ ಮಾಡಿ ಅರ್ಧ ಕೆಜಿ ಮಾದರಿಯನ್ನು ನಿಮ್ಮ ಹತ್ತಿರದ ರೈತ ಸಂಪರ್ಕ ಕೇಂದ್ರಕ್ಕೆ (RSK) ಕೊಡಿ. ಕೇವಲ ₹30 - ₹50 ಶುಲ್ಕವಿರುತ್ತದೆ."),
        ("VKB-037", "green_manure", "ಹಸಿರೆಲೆ ಗೊಬ್ಬರಕ್ಕೆ ಸೆಣಬು ಹೇಗೆ ಬೆಳೆಯುವುದು?", ["ಹಸಿರೆಲೆ ಗೊಬ್ಬರ", "ಸೆಣಬು", "ಡೈಂಚಾ"], "ಮುಂಗಾರು ಮಳೆ ಮುಂಚೆ ಎಕರೆಗೆ 15-20 ಕೆಜಿ ಸೆಣಬು ಅಥವಾ ಡೈಂಚಾ ಬಿತ್ತನೆ ಮಾಡಿ. ಬೆಳೆಯು 45-50 ದಿನಗಳಲ್ಲಿ 50% ಹೂವಾಡುವ ಹಂತಕ್ಕೆ ಬಂದಾಗ ರೋಟಾವೇಟರ್‌ನಿಂದ ಮಣ್ಣಿನಲ್ಲಿ ಕಡಿದು ಮಗುಚಿ ಹಾಕಿ. ಇದರಿಂದ 1 ಎಕರೆಗೆ 8-10 ಟನ್ ಹಸಿರೆಲೆ ಸೇರಿ 35 ಕೆಜಿ ಸಾರಜನಕ ಸಿಗುತ್ತದೆ."),
        ("VKB-038", "bio_fertilizer", "ರೈಜೋಬಿಯಂ ಮತ್ತು ಪಿಎಸ್‌ಬಿ ಬಳಕೆ ಹೇಗೆ?", ["ಜೈವಿಕ ಗೊಬ್ಬರ", "ರೈಜೋಬಿಯಂ", "ಪಿಎಸ್‌ಬಿ"], "ರೈಜೋಬಿಯಂ ತೊಗರಿ, ಶೇಂಗಾ ಬೀಜೋಪಚಾರಕ್ಕೆ (200 ಗ್ರಾಂ/ಎಕರೆ ಬೀಜಕ್ಕೆ). ಪಿಎಸ್‌ಬಿ (PSB) ಮಣ್ಣಿನಲ್ಲಿ ಕರಗದ ರಂಜಕವನ್ನು ಕರಗಿಸುತ್ತದೆ. 2 ಕೆಜಿ ಪಿಎಸ್‌ಬಿಯನ್ನು ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದಲ್ಲಿ ಬೆರೆಸಿ ಬುಡಕ್ಕೆ ಹಾಕಿ."),
        ("VKB-039", "lime_gypsum", "ಹುಳಿ ಮಣ್ಣಿಗೆ ಸುಣ್ಣ ಯಾವಾಗ ಹಾಕಬೇಕು?", ["ಸುಣ್ಣ", "ಜಿಪ್ಸಮ್", "ಆಮ್ಲೀಯ ಮಣ್ಣು", "ಹುಳಿ ಮಣ್ಣು"], "ಮಣ್ಣಿನ pH 6.5 ಕ್ಕಿಂತ ಕಡಿಮೆಯಿದ್ದರೆ (ಆಮ್ಲೀಯ ಮಣ್ಣು) ಎಕರೆಗೆ 200-400 ಕೆಜಿ ಕೃಷಿ ಸುಣ್ಣ ಬಿತ್ತನೆಗೆ 1 ತಿಂಗಳು ಮುಂಚೆ ಹಾಕಿ. ಮಣ್ಣು ಕ್ಷಾರೀಯವಾಗಿದ್ದರೆ (pH > 8.0) ಎಕರೆಗೆ 500 ಕೆಜಿ ಕೃಷಿ ಜಿಪ್ಸಮ್ ಹಾಕಿ."),
        ("VKB-040", "waste_decomposer", "ವೇಸ್ಟ್ ಡಿಕಂಪೋಸರ್ ಹೇಗೆ ಬಳಸಬೇಕು?", ["ವೇಸ್ಟ್ ಡಿಕಂಪೋಸರ್", "ಕಾಂಪೋಸ್ಟ್", "ಬೆಳೆ ತ್ಯಾಜ್ಯ"], "200 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ 2 ಕೆಜಿ ಬೆಲ್ಲ ಕರಗಿಸಿ 1 ಬಾಟಲ್ ವೇಸ್ಟ್ ಡಿಕಂಪೋಸರ್ ಹಾಕಿ ನೆರಳಿನಲ್ಲಿ 5-7 ದಿನ ಇಡಿ. ಪ್ರತಿದಿನ ಕಲಕಿ. ಈ ದ್ರಾವಣವನ್ನು ಬೆಳೆ ತ್ಯಾಜ್ಯ, ಕಳೆ, ಸೆಗಣಿ ಮೇಲೆ ಸಿಂಪಡಿಸಿದರೆ 30-40 ದಿನಗಳಲ್ಲಿ ಉತ್ಕೃಷ್ಟ ಗೊಬ್ಬರವಾಗುತ್ತದೆ."),
        ("VKB-041", "saline_soil", "ಚೌಳು ಮಣ್ಣು ಸುಧಾರಣೆ ಹೇಗೆ?", ["ಉಪ್ಪು ಮಣ್ಣು", "ಲವಣಾಂಶ", "ಚೌಳು", "ಡ್ರೈನೇಜ್"], "ಜಮೀನಿನಲ್ಲಿ ಹೆಚ್ಚುವರಿ ನೀರು ಹೊರಹೋಗಲು ಬಸಿಗಾಲುವೆ (Drainage) ನಿರ್ಮಿಸಿ. ಎಕರೆಗೆ 500 ಕೆಜಿ ಕೃಷಿ ಜಿಪ್ಸಮ್ ಚೆಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಹಸಿರೆಲೆ ಗೊಬ್ಬರ ಬೆಳೆಸಿ ಮಗುಚಿ ಹಾಕಿ."),
        ("VKB-042", "iron_deficiency", "ಮೆಕ್ಕೆಜೋಳದಲ್ಲಿ ಎಲೆ ಬಿಳಿಯಾಗುತ್ತಿರುವುದಕ್ಕೆ ಮದ್ದು ಏನು?", ["ಕಬ್ಬಿಣದ ಕೊರತೆ", "ಬಿಳಿ ಎಲೆ", "ಹಳದಿ ಎಲೆ", "ಫೆರಸ್ ಸಲ್ಫೇಟ್"], "ಇದು ಕಬ್ಬಿಣದ ಕೊರತೆ (Iron Chlorosis). ಪರಿಹಾರ: 1 ಲೀಟರ್ ನೀರಿಗೆ 5 ಗ್ರಾಂ ಫೆರಸ್ ಸಲ್ಫೇಟ್ (Ferrous Sulphate) + 1 ಗ್ರಾಂ ಸಿಟ್ರಿಕ್ ಆಮ್ಲ (ಲಿಂಬೆ ಉಪ್ಪು) ಬೆರೆಸಿ ವಾರದ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಸಿಂಪಡಿಸಿ."),
        ("VKB-043", "calcium_boron", "ಟೊಮೆಟೊ ಹಣ್ಣು ಬಿರುಕು ಬಿಡದಂತೆ ಏನು ಮಾಡಬೇಕು?", ["ಕ್ಯಾಲ್ಸಿಯಂ", "ಮೆಗ್ನೀಸಿಯಂ", "ಹಣ್ಣಿನ ತಳ ಕೊಳೆ", "ಬೋರಾನ್"], "ಹಣ್ಣು ಬಿರುಕು ಮತ್ತು ತಳ ಕೊಳೆಯುವುದಕ್ಕೆ ಕ್ಯಾಲ್ಸಿಯಂ ಮತ್ತು ಬೋರಾನ್ ಕೊರತೆ ಕಾರಣ. 1 ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕ್ಯಾಲ್ಸಿಯಂ ನೈಟ್ರೇಟ್ ಮತ್ತು 1 ಗ್ರಾಂ ಬೋರಾಕ್ಸ್ ಬೆರೆಸಿ ಹೂವು-ಕಾಯಿ ಕಟ್ಟುವ ಹಂತದಲ್ಲಿ ಸಿಂಪಡಿಸಿ."),
        ("VKB-044", "micronutrient_grade", "ಕರ್ನಾಟಕ ಕೃಷಿ ಇಲಾಖೆಯ ಲಘು ಪೋಷಕಾಂಶ ಮಿಶ್ರಣ (Grade) ಯಾವುದು?", ["ಲಘು ಪೋಷಕಾಂಶ", "ಗ್ರೇಡ್", "ಜಿಂಕ್", "ಕಬ್ಬಿಣ"], "ತರಕಾರಿ ಬೆಳೆಗಳಿಗೆ ಕೃಷಿ ಇಲಾಖೆಯ 'ಗ್ರೇಡ್-1' ಅಥವಾ 'ಗ್ರೇಡ್-4' ಲಘು ಪೋಷಕಾಂಶ ಮಿಶ್ರಣವನ್ನು 1 ಲೀಟರ್ ನೀರಿಗೆ 2.5 ಗ್ರಾಂ ಬೆರೆಸಿ ಬೆಳವಣಿಗೆಯ ಹಂತದಲ್ಲಿ ಸಿಂಪಡಿಸಬೇಕು."),
        ("VKB-045", "compost_making", "ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಬೇಗ ಕಳಿಯುವಂತೆ ಮಾಡುವುದು ಹೇಗೆ?", ["ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ", "ಸೆಗಣಿ", "ಕಾಂಪೋಸ್ಟ್ ಗುಂಡಿ"], "ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದ ಗುಂಡಿಗೆ 3 ಅಡಿ ಎತ್ತರದ ಪದರ ಮಾಡಿ ಅದರ ಮೇಲೆ ಸೂಪರ್ ಫಾಸ್ಫೇಟ್ (SSP) 5 ಕೆಜಿ ಮತ್ತು ಸಗಣಿ-ನೀರಿನ ಕಷಾಯ ಅಥವಾ ಡಿಕಂಪೋಸರ್ ಸಿಂಪಡಿಸಿ ಮುಚ್ಚಿದರೆ 60 ದಿನಗಳಲ್ಲಿ ಕಪ್ಪು ಬಣ್ಣದ ಪುಡಿ ಗೊಬ್ಬರ ಸಿದ್ಧವಾಗುತ್ತದೆ."),
        ("VKB-046", "foliar_feeding", "ಎಲೆ ಸಿಂಪಡಣೆ ಗೊಬ್ಬರವನ್ನು ಯಾವ ಸಮಯದಲ್ಲಿ ಮಾಡಬೇಕು?", ["ಎಲೆ ಸಿಂಪಡಣೆ", "ಫೋಲಿಯಾರ್", "ಬೆಳಿಗ್ಗೆ", "ಸಂಜೆ"], "ಎಲೆ ಸಿಂಪಡಣೆಯನ್ನು ಬೆಳಿಗ್ಗೆ 7 ರಿಂದ 10 ಗಂಟೆ ಒಳಗೆ ಅಥವಾ ಸಂಜೆ 4 ರಿಂದ 6 ಗಂಟೆ ಒಳಗೆ ಮಾಡಬೇಕು. ಬಿರುಬಿಸಿಲಿನಲ್ಲಿ ಸಿಂಪಡಿಸಿದರೆ ಎಲೆಗಳು ಸುಟ್ಟುಹೋಗುತ್ತವೆ."),
        ("VKB-047", "sulphur_oilseeds", "ಶೇಂಗಾ ಮತ್ತು ಸೂರ್ಯಕಾಂತಿಗೆ ಗಂಧಕ (ಸಲ್ಫರ್) ಯಾಕೆ ಬೇಕು?", ["ಸಲ್ಫರ್", "ಗಂಧಕ", "ಎಣ್ಣೆ ಅಂಶ", "ಶೇಂಗಾ"], "ಗಂಧಕವು ಎಣ್ಣೆಕಾಳುಗಳಲ್ಲಿ ಎಣ್ಣೆಯ ಅಂಶವನ್ನು 3-5% ಹೆಚ್ಚಿಸುತ್ತದೆ ಮತ್ತು ಕಾಯಿಗಳನ್ನು ಗಟ್ಟಿಗೊಳಿಸುತ್ತದೆ. ಎಕರೆಗೆ 10-15 ಕೆಜಿ ಬೆಂಟೋನೈಟ್ ಸಲ್ಫರ್ ಅಥವಾ ಜಿಪ್ಸಮ್ ನೀಡಬೇಕು."),
        ("VKB-048", "magnesium_spray", "ಹತ್ತಿ ಮತ್ತು ತರಕಾರಿಗಳಲ್ಲಿ ಕೆಂಪು ಎಲೆ ಬಂದರೆ ಏನು ಮಾಡಬೇಕು?", ["ಮೆಗ್ನೀಸಿಯಂ ಸಲ್ಫೇಟ್", "ಕೆಂಪು ಎಲೆ", "ಹತ್ತಿ"], "ಹತ್ತಿಯಲ್ಲಿ ಎಲೆಗಳು ಕೆಂಪಾಗುವುದು ಮೆಗ್ನೀಸಿಯಂ ಕೊರತೆಯಿಂದ. ಪರಿಹಾರ: ಮೆಗ್ನೀಸಿಯಂ ಸಲ್ಫೇಟ್ 10 ಗ್ರಾಂ/ಲೀಟರ್ + 19:19:19 (5 ಗ್ರಾಂ/ಲೀ) ಬೆರೆಸಿ ಸಿಂಪಡಿಸಿ."),
        ("VKB-049", "root_growth_hormone", "ಗಿಡದ ಬೇರುಗಳು ಚೆನ್ನಾಗಿ ಬೆಳೆಯಲು ಏನು ನೀಡಬೇಕು?", ["ಬೇರು ಬೆಳವಣಿಗೆ", "ಹ್ಯೂಮಿಕ್ ಆಸಿಡ್", "ಮೈಕೋರೈಜಾ"], "ಹ್ಯೂಮಿಕ್ ಆಸಿಡ್ (Humic Acid 12%) 3 ಮಿ.ಲೀ/ಲೀಟರ್ ಅಥವಾ ಮೈಕೋರೈಜಾ (VAM) ಜೈವಿಕ ಶಿಲೀಂಧ್ರವನ್ನು ಮಣ್ಣಿಗೆ ನೀಡಿದರೆ ತಂತು ಬೇರುಗಳ ಬೆಳವಣಿಗೆ ದುಪ್ಪಟ್ಟಾಗುತ್ತದೆ."),
        ("VKB-050", "potassium_schoenite", "ಪೊಟ್ಯಾಶಿಯಂ ಶೋನೈಟ್ ಎಂದರೇನು?", ["ಪೊಟ್ಯಾಶಿಯಂ ಶೋನೈಟ್", "ಪೊಟ್ಯಾಷ್", "ಮೆಗ್ನೀಸಿಯಂ"], "ಪೊಟ್ಯಾಶಿಯಂ ಶೋನೈಟ್‌ನಲ್ಲಿ 23% ಪೊಟ್ಯಾಷ್ ಮತ್ತು 11% ಮೆಗ್ನೀಸಿಯಂ ಇರುತ್ತದೆ. ಇದು ಕ್ಲೋರೈಡ್ ಮುಕ್ತವಾಗಿದ್ದು, ದ್ರಾಕ್ಷಿ, ದಾಳಿಂಬೆ ಮತ್ತು ತರಕಾರಿಗಳಿಗೆ ಡ್ರಿಪ್ ಮೂಲಕ ನೀಡಲು ಅತ್ಯುತ್ತಮ.")
    ]

