    # Category 4: Crop Diseases & Fungicides (76 - 100)
    disease_qas = [
        ("VKB-071", "ragi_blast", "ರಾಗಿ ಬೆಂಕಿ ರೋಗ (ಬ್ಲಾಸ್ಟ್) ನಿಯಂತ್ರಣ ಹೇಗೆ?", ["ರಾಗಿ", "ಬೆಂಕಿ ರೋಗ", "ಬ್ಲಾಸ್ಟ್", "ಟ್ರೈಸೈಕ್ಲಾಜೋಲ್"], "ಬೀಜೋಪಚಾರಕ್ಕೆ ಕಾರ್ಬೆಂಡಾಜಿಮ್ 2 ಗ್ರಾಂ/ಕೆಜಿ. ಬೆಳೆಯ ಮೇಲೆ ಕಂಡಾಗ ಟ್ರೈಸೈಕ್ಲಾಜೋಲ್ 75% ಡಬ್ಲ್ಯೂಪಿ 0.6 ಗ್ರಾಂ/ಲೀಟರ್ (15 ಲೀ ಪಂಪ್‌ಗೆ 9 ಗ್ರಾಂ) ಸಿಂಪಡಿಸಿ."),
        ("VKB-072", "tomato_blight", "ಟೊಮೆಟೊ ಅಂಗಮಾರಿ ರೋಗಕ್ಕೆ ಔಷಧ ಯಾವುದು?", ["ಟೊಮೆಟೊ", "ಅಂಗಮಾರಿ ರೋಗ", "ಬ್ಲೈಟ್", "ಮ್ಯಾಂಕೋಜೆಬ್", "ರಿಡೋಮಿಲ್"], "ಮುನ್ನೆಚ್ಚರಿಕೆಗೆ ಮ್ಯಾಂಕೋಜೆಬ್ 2.5 ಗ್ರಾಂ/ಲೀ. ರೋಗ ತೀವ್ರವಿದ್ದಾಗ ಮೆಟಾಲಾಕ್ಸಿಲ್ + ಮ್ಯಾಂಕೋಜೆಬ್ (ರಿಡೋಮಿಲ್ ಗೋಲ್ಡ್) 2 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-073", "tomato_wilt", "ಟೊಮೆಟೊ ಸೊರಗು ರೋಗಕ್ಕೆ (Bacterial Wilt) ಪರಿಹಾರವೇನು?", ["ಟೊಮೆಟೊ", "ಸೊರಗು ರೋಗ", "ಬ್ಲೀಚಿಂಗ್ ಪೌಡರ್", "ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್"], "ಬುಡಕ್ಕೆ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ 0.5 ಗ್ರಾಂ + ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 2.5 ಗ್ರಾಂ/ಲೀ ಡ್ರೆಂಚಿಂಗ್ ಮಾಡಿ. ನೀರಾವರಿ ನೀರಿನಲ್ಲಿ ಎಕರೆಗೆ 2 ಕೆಜಿ ಬ್ಲೀಚಿಂಗ್ ಪೌಡರ್ ಹಾಯಿಸಿ."),
        ("VKB-074", "chilli_dieback", "ಮೆಣಸಿನಕಾಯಿ ಕೊಂಬೆ ಒಣಗುವಿಕೆ ಮತ್ತು ಕಾಯಿ ಕೊಳೆ ರೋಗಕ್ಕೆ ಮದ್ದು ಏನು?", ["ಮೆಣಸಿನಕಾಯಿ", "ಕೊಂಬೆ ಒಣಗುವಿಕೆ", "ಡೈಬ್ಯಾಕ್", "ಆಂಥ್ರಾಕ್ನೋಸ್"], "ಅಜಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ + ಡೈಫೆನೋಕೊನಜೋಲ್ (ಕಸ್ಟೋಡಿಯಾ) 1 ಮಿ.ಲೀ/ಲೀ ಅಥವಾ ನೇಟಿವೋ 0.5 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-075", "tur_wilt", "ತೊಗರಿ ನೆಟೆ ರೋಗ ತಡೆಯುವುದು ಹೇಗೆ?", ["ತೊಗರಿ", "ನೆಟೆ ರೋಗ", "ಟ್ರೈಕೋಡರ್ಮ", "ಜಿಆರ್‌ಜಿ-152"], "ರೋಗ ನಿರೋಧಕ ತಳಿ ಜಿಆರ್‌ಜಿ-152 ಬಿತ್ತಿ. ಬೀಜಕ್ಕೆ 1 ಕೆಜಿಗೆ 10 ಗ್ರಾಂ ಟ್ರೈಕೋಡರ್ಮ ಬೆರೆಸಿ ಬೀಜೋಪಚಾರ ಮಾಡಿ. ಎಕರೆಗೆ 2 ಕೆಜಿ ಟ್ರೈಕೋಡರ್ಮ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದಲ್ಲಿ ಹಾಕಿ."),
        ("VKB-076", "onion_purple_blotch", "ಈರುಳ್ಳಿ ನೇರಳೆ ಮಚ್ಚೆ ರೋಗಕ್ಕೆ ಔಷಧಿ ಯಾವುದು?", ["ಈರುಳ್ಳಿ", "ನೇರಳೆ ಮಚ್ಚೆ ರೋಗ", "ಟೆಬುಕೊನಜೋಲ್"], "ಟೆಬುಕೊನಜೋಲ್ 1.5 ಮಿ.ಲೀ/ಲೀಟರ್ ಅಥವಾ ಹೆಕ್ಸಾಕೊನಜೋಲ್ 1.5 ಮಿ.ಲೀ/ಲೀ ಜೊತೆಗೆ ಅಂಟು (ಸ್ಟಿಕ್ಕರ್) ಬೆರೆಸಿ ಸಿಂಪಡಿಸಿ."),
        ("VKB-077", "powdery_mildew", "ಎಲೆಗಳ ಮೇಲೆ ಬಿಳಿ ಬೂದಿ ರೋಗಕ್ಕೆ ಔಷಧಿ ಏನು?", ["ಬೂದಿ ರೋಗ", "ಪೌಡರಿ ಮಿಲ್ಡ್ಯೂ", "ಸಲ್ಫರ್"], "ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ (Wettable Sulphur) 2.5 ಗ್ರಾಂ/ಲೀಟರ್ ಅಥವಾ ಡೈಫೆನೋಕೊನಜೋಲ್ 0.5 ಮಿ.ಲೀ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-078", "arecanut_kole", "ಅಡಿಕೆ ಕೊಳೆ ರೋಗ (ಮಹಾಳಿ) ತಡೆಯಲು ಏನು ಮಾಡಬೇಕು?", ["ಅಡಿಕೆ", "ಕೊಳೆ ರೋಗ", "ಮಹಾಳಿ", "ಬೋರ್ಡೋ ದ್ರಾವಣ"], "ಮಳೆಗಾಲ ಆರಂಭವಾಗುವ ಮುನ್ನ ಮೇ ಅಂತ್ಯದಲ್ಲಿ 1% ಬೋರ್ಡೋ ದ್ರಾವಣವನ್ನು ಅಡಿಕೆ ಗೊನೆಗಳಿಗೆ ಚೆನ್ನಾಗಿ ಸಿಂಪಡಿಸಿ. 40 ದಿನದ ನಂತರ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸಿ."),
        ("VKB-079", "bordeaux_preparation", "1% ಬೋರ್ಡೋ ದ್ರಾವಣ ತಯಾರಿಸುವುದು ಹೇಗೆ?", ["ಬೋರ್ಡೋ ದ್ರಾವಣ", "ಮೈಲುತುತ್ತ", "ಸುಣ್ಣ"], "100 ಲೀ ನೀರಿಗೆ: 1 ಕೆಜಿ ಮೈಲುತುತ್ತವನ್ನು 50 ಲೀ ಪ್ಲಾಸ್ಟಿಕ್ ಡ್ರಮ್‌ನಲ್ಲಿ ಕರಗಿಸಿ. ಇನ್ನೊಂದು ಪಾತ್ರೆಯಲ್ಲಿ 1 ಕೆಜಿ ಸುಣ್ಣವನ್ನು 50 ಲೀ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ. ಮೈಲುತುತ್ತವನ್ನು ಸುಣ್ಣದ ನೀರಿಗೆ ಸುರಿದು ಕಲಕಿ."),
        ("VKB-080", "ginger_rot", "ಶುಂಠಿ ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ನಿಯಂತ್ರಣ ಹೇಗೆ?", ["ಶುಂಠಿ", "ಗಡ್ಡೆ ಕೊಳೆ", "ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್"], "ಬೀಜದ ಶುಂಠಿಯನ್ನು ರಿಡೋಮಿಲ್ (3 ಗ್ರಾಂ/ಲೀ) ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷ ನೆನೆಸಿ ಬಿತ್ತಿ. ಹೊಲದಲ್ಲಿ ಕೊಳೆ ಕಂಡರೆ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 3 ಗ್ರಾಂ/ಲೀ ಬುಡಕ್ಕೆ ಸುರಿಯಿರಿ."),
        ("VKB-081", "banana_panama", "ಬಾಳೆ ಗಿಡ ಹಳದಿಯಾಗಿ ಒಣಗುವ ಪನಾಮಾ ಸೊರಗು ರೋಗಕ್ಕೆ ಮದ್ದು ಏನು?", ["ಬಾಳೆ", "ಪನಾಮಾ ರೋಗ", "ಕಾರ್ಬೆಂಡಾಜಿಮ್"], "ಕಾರ್ಬೆಂಡಾಜಿಮ್ 2 ಗ್ರಾಂ/ಲೀಟರ್ ದ್ರಾವಣವನ್ನು ಬಾಳೆ ಬುಡಕ್ಕೆ ಸುರಿಯಿರಿ ಮತ್ತು ಬಾಳೆ ಕಂದನ್ನು ನೆಡುವ ಮುನ್ನ 20 ನಿಮಿಷ ಅದೇ ದ್ರಾವಣದಲ್ಲಿ ಅದ್ದಿ."),
        ("VKB-082", "pomegranate_telya", "ದಾಳಿಂಬೆ ತೇಲ್ಯ (ಬ್ಯಾಕ್ಟೀರಿಯಲ್ ಬ್ಲೈಟ್) ರೋಗ ತಡೆಗಟ್ಟುವುದು ಹೇಗೆ?", ["ದಾಳಿಂಬೆ", "ತೇಲ್ಯ ರೋಗ", "ಬ್ಯಾಕ್ಟೀರಿಯಾ", "ಬೋರ್ಡೋ"], "ರೋಗಗ್ರಸ್ತ ಕೊಂಬೆಗಳನ್ನು 2 ಇಂಚು ಕೆಳಕ್ಕೆ ಕತ್ತರಿಸಿ ಬೋರ್ಡೋ ಪೇಸ್ಟ್ ಹಚ್ಚಿ. ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ 0.5 ಗ್ರಾಂ + ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 2.5 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-083", "damping_off", "ಸಸಿ ಮಡಿಯಲ್ಲಿ ಸಸಿ ಕೊಳೆತು ಬೀಳುವುದಕ್ಕೆ (ಡ್ಯಾಂಪಿಂಗ್ ಆಫ್) ಏನು ಮಾಡಬೇಕು?", ["ಸಸಿ ಮಡಿ", "ಸಸಿ ಕೊಳೆ", "ಡ್ಯಾಂಪಿಂಗ್ ಆಫ್", "ಕ್ಯಾಪ್ಟಾನ್"], "ಸಸಿ ಮಡಿಗೆ ಕ್ಯಾಪ್ಟಾನ್ ಅಥವಾ ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 2.5 ಗ್ರಾಂ/ಲೀ ದ್ರಾವಣದಿಂದ ಸಿಂಪಡಿಸಿ ಮಣ್ಣು ನೆನೆಯುವಂತೆ ಮಾಡಿ. ಮಡಿಗಳಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಿ."),
        ("VKB-084", "downy_mildew", "ದ್ರಾಕ್ಷಿ ಮತ್ತು ಸೌತೆ ಜಾತಿಯ ಡೌನಿ ಮಿಲ್ಡ್ಯೂ (ಬೂಸ್ಟು ರೋಗ) ನಿಯಂತ್ರಣ ಹೇಗೆ?", ["ಡೌನಿ ಮಿಲ್ಡ್ಯೂ", "ಬೂಸ್ಟು ರೋಗ", "ಅಲಿಯೆಟ್", "ರಿಡೋಮಿಲ್"], "ಫೋಸೆಟೈಲ್-ಎಎಲ್ (ಅಲಿಯೆಟ್) 2 ಗ್ರಾಂ/ಲೀ ಅಥವಾ ಮೆಟಾಲಾಕ್ಸಿಲ್ + ಮ್ಯಾಂಕೋಜೆಬ್ 2 ಗ್ರಾಂ/ಲೀಟರ್ ಎಲೆಗಳ ತಳಭಾಗಕ್ಕೆ ಸಿಂಪಡಿಸಿ."),
        ("VKB-085", "cercospora_leafspot", "ಶೇಂಗಾ ಟಿಕ್ಕಾ ಎಲೆ ಚುಕ್ಕೆ ರೋಗಕ್ಕೆ ಯಾವ ಔಷಧಿ ಸಿಂಪಡಿಸಬೇಕು?", ["ಶೇಂಗಾ", "ಟಿಕ್ಕಾ ರೋಗ", "ಎಲೆ ಚುಕ್ಕೆ", "ಹೆಕ್ಸಾಕೊನಜೋಲ್"], "ಹೆಕ್ಸಾಕೊನಜೋಲ್ 5% ಇ.ಸಿ 1.5 ಮಿ.ಲೀ/ಲೀ ಅಥವಾ ಟೆಬುಕೊನಜೋಲ್ 1 ಮಿ.ಲೀ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-086", "rust_pulses", "ದ್ವಿದಳ ಧಾನ್ಯಗಳಲ್ಲಿ ತುಕ್ಕು ರೋಗ (Rust) ಬಂದರೆ ಏನು ಮಾಡಬೇಕು?", ["ತುಕ್ಕು ರೋಗ", "ಕಾಳು ಬೆಳೆ", "ಪ್ರೊಪಿಕೊನಜೋಲ್"], "ಪ್ರೊಪಿಕೊನಜೋಲ್ (ಟಿಲ್ಟ್) 1 ಮಿ.ಲೀ/ಲೀ ಅಥವಾ ಮ್ಯಾಂಕೋಜೆಬ್ 2.5 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-087", "collar_rot", "ಗಿಡದ ನೆಲಮಟ್ಟದ ಕಾಂಡ ಕೊಳೆಯುವುದಕ್ಕೆ (ಕಾಲರ್ ರಾಟ್) ಏನು ಮಾಡಬೇಕು?", ["ಕಾಂಡ ಕೊಳೆ", "ಕಾಲರ್ ರಾಟ್", "ಟ್ರೈಕೋಡರ್ಮ"], "ಟ್ರೈಕೋಡರ್ಮ 10 ಗ್ರಾಂ/ಲೀ ಅಥವಾ ಕಾರ್ಬೆಂಡಾಜಿಮ್ 2 ಗ್ರಾಂ/ಲೀ ಬೆರೆಸಿ ಕಾಂಡ ಮತ್ತು ಬುಡದ ಮಣ್ಣಿಗೆ ಡ್ರೆಂಚಿಂಗ್ ಮಾಡಿ."),
        ("VKB-088", "root_knot_nematode", "ಬೇರುಗಳಲ್ಲಿ ಗಂಟುಗಳು (ಜಂತುಹುಳು) ಆದರೆ ಪರಿಹಾರವೇನು?", ["ಬೇರು ಗಂಟು", "ನೆಮಟೋಡ್", "ಜಂತುಹುಳು", "ಪ್ಯೂರಿಪಾಸ್ಪೋರಿಯಂ"], "ಪ್ಯೂರಿಪಾಸ್ಪೋರಿಯಂ ಲಿಲಾಸಿನಸ್ (Paecilomyces) ಜೈವಿಕ ಶಿಲೀಂಧ್ರ 2 ಕೆಜಿ ಅಥವಾ ಬೇವಿನ ಹಿಂಡಿ 150 ಕೆಜಿ ಎಕರೆಗೆ ಮಣ್ಣಿಗೆ ಸೇರಿಸಿ."),
        ("VKB-089", "yellow_mosaic", "ತೊಗರಿ ಮತ್ತು ಉದ್ದಿನ ಹಳದಿ ಮೊಸಾಯಿಕ್ ವೈರಸ್ ತಡೆಯುವುದು ಹೇಗೆ?", ["ಹಳದಿ ಮೊಸಾಯಿಕ್", "ವೈರಸ್", "ಬಿಳಿ ನೊಣ"], "ಇದು ಬಿಳಿ ನೊಣದಿಂದ ಬರುತ್ತದೆ. ರೋಗಗ್ರಸ್ತ ಗಿಡಗಳನ್ನು ತಕ್ಷಣ ಕಿತ್ತು ಸುಟ್ಟುಹಾಕಿ ಬಿಳಿ ನೊಣ ನಿಯಂತ್ರಣಕ್ಕೆ ಅಸಿಟಾಮಿಪ್ರಿಡ್ 0.3 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-090", "citrus_canker", "ಲಿಂಬೆ ಹಣ್ಣಿನ ಮೇಲೆ ಕಜ್ಜಿ ಮಚ್ಚೆ (ಕ್ಯಾಂಕರ್) ಬಂದರೆ ಏನು ಮಾಡಬೇಕು?", ["ಲಿಂಬೆ ಕ್ಯಾಂಕರ್", "ಕಜ್ಜಿ ರೋಗ", "ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್"], "ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ 1 ಗ್ರಾಂ + ಕಾಪರ್ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 30 ಗ್ರಾಂ ಅನ್ನು 10 ಲೀಟರ್ ನೀರಿಗೆ ಬೆರೆಸಿ ಹೊಸ ಚಿಗುರು ಮತ್ತು ಕಾಯಿ ಕಟ್ಟುವಾಗ ಸಿಂಪಡಿಸಿ."),
        ("VKB-091", "sooty_mould", "ಎಲೆಗಳ ಮೇಲೆ ಕಪ್ಪು ಕಾಡಿಗೆ ಮಸಿ (Sooty mould) ಬಂದರೆ ಏನು ಮಾಡಬೇಕು?", ["ಕಪ್ಪು ಮಸಿ", "ಕಾಡಿಗೆ ರೋಗ", "ರಸ ಹೀರುವ ಕೀಟ"], "ಮಸಿ ರೋಗವು ಜಿಗಿಹುಳುಗಳ ಜೇನಿನ ದ್ರವದಿಂದ ಬರುತ್ತದೆ. ಮೈದಾ ಹಿಟ್ಟಿನ ಗಂಜಿ (1 ಲೀಟರ್ ನೀರಿಗೆ 20 ಗ್ರಾಂ ಮೈದಾ ಕುದಿಸಿ) ಸಿಂಪಡಿಸಿದರೆ ಮಸಿ ಒಣಗಿ ಕಿತ್ತು ಬೀಳುತ್ತದೆ."),
        ("VKB-092", "sheath_blight_paddy", "ಭತ್ತದ ಪರೆ ರೋಗಕ್ಕೆ (Sheath Blight) ಯಾವ ಶಿಲೀಂಧ್ರನಾಶಕ ಉತ್ತಮ?", ["ಭತ್ತದ ಪರೆ ರೋಗ", "ಶೀತ್ ಬ್ಲೈಟ್", "ವ್ಯಾಲಿಡಾಮೈಸಿನ್"], "ವ್ಯಾಲಿಡಾಮೈಸಿನ್ 3% ಎಲ್ 2 ಮಿ.ಲೀ/ಲೀ ಅಥವಾ ಅಜಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್ + ಡೈಫೆನೋಕೊನಜೋಲ್ 1 ಮಿ.ಲೀ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-093", "anthracnose_mango", "ಮಾವಿನ ಹೂಗೊಂಚಲು ಕಪ್ಪಾಗಿ ಉದುರುವುದಕ್ಕೆ (ಆಂಥ್ರಾಕ್ನೋಸ್) ಪರಿಹಾರವೇನು?", ["ಮಾವಿನ ಹೂವು", "ಆಂಥ್ರಾಕ್ನೋಸ್", "ಕಾರ್ಬೆಂಡಾಜಿಮ್"], "ಹೂ ಮೊಗ್ಗು ಬಿಡುವಾಗ ಕಾರ್ಬೆಂಡಾಜಿಮ್ 1 ಗ್ರಾಂ/ಲೀ ಅಥವಾ ಮ್ಯಾಂಕೋಜೆಬ್ 2 ಗ್ರಾಂ/ಲೀ ಸಿಂಪಡಿಸಿ."),
        ("VKB-094", "trichoderma_soil", "ಟ್ರೈಕೋಡರ್ಮ ವಿರಿಡೆಯನ್ನು ಮಣ್ಣಿಗೆ ಹೇಗೆ ಬಳಸಬೇಕು?", ["ಟ್ರೈಕೋಡರ್ಮ", "ಜೈವಿಕ ಶಿಲೀಂಧ್ರ", "ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ"], "2 ಕೆಜಿ ಟ್ರೈಕೋಡರ್ಮ ಪುಡಿಯನ್ನು 100 ಕೆಜಿ ಕಳಿತ ತೇವಾಂಶವಿರುವ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರದಲ್ಲಿ ಬೆರೆಸಿ ನೆರಳಿನಲ್ಲಿ 7 ದಿನ ಗೋಣಿಚೀಲ ಮುಚ್ಚಿಟ್ಟು ನಂತರ ಮಣ್ಣಿಗೆ ಹರಡಿ."),
        ("VKB-095", "pseudomonas_spray", "ಸೂಡೋಮೊನಾಸ್ ಫ್ಲೋರೊಸೆನ್ಸ್ ಜೈವಿಕ ಔಷಧ ಸಿಂಪಡಣೆ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ಸೂಡೋಮೊನಾಸ್", "ಜೈವಿಕ ಔಷಧ", "ಬ್ಯಾಕ್ಟೀರಿಯಾ"], "1 ಲೀಟರ್ ನೀರಿಗೆ 5 ರಿಂದ 10 ಗ್ರಾಂ ಸೂಡೋಮೊನಾಸ್ ಪುಡಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಿದರೆ ಶಿಲೀಂಧ್ರ ಮತ್ತು ಬ್ಯಾಕ್ಟೀರಿಯಾ ರೋಗಗಳು ಪ್ರಾಕೃತಿಕವಾಗಿ ನಿಯಂತ್ರಣವಾಗುತ್ತವೆ.")
    ]

