    # Category 5: Sowing & Varieties (96 - 120)
    sowing_qas = [
        ("VKB-096", "ragi_varieties_detail", "ರಾಗಿ ಬಿತ್ತನೆಗೆ ಯಾವ ತಳಿಗಳು ಹೆಚ್ಚು ಸೂಕ್ತ?", ["ರಾಗಿ ತಳಿ", "ಎಂಎಲ್-365", "ಜಿಪಿಯು-28", "ಎಂಆರ್-6"], "ಕರ್ನಾಟಕದ ದಕ್ಷಿಣ ಒಣವಲಯಕ್ಕೆ ಎಂಎಲ್-365, ಜಿಪಿಯು-28 ಮತ್ತು ಎಂಆರ್-6 ಅತ್ಯಂತ ಯಶಸ್ವಿ ತಳಿಗಳು. ನೀರಾವರಿ ಬೆಳೆಗೆ ಜಿಪಿಯು-48 ತಳಿ ಸೂಕ್ತ."),
        ("VKB-097", "seed_rate_calculator", "1 ಹೆಕ್ಟೇರ್ ಮತ್ತು 1 ಎಕರೆಗೆ ರಾಗಿ ಬಿತ್ತನೆ ಬೀಜ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ರಾಗಿ ಬೀಜ ಪ್ರಮಾಣ", "ಹೆಕ್ಟೇರ್", "ಎಕರೆ"], "ಸಾಲು ಕೂರಿಗೆ ಬಿತ್ತನೆಗೆ ಹೆಕ್ಟೇರಿಗೆ 5 ಕೆಜಿ (ಎಕರೆಗೆ 2 ರಿಂದ 2.5 ಕೆಜಿ) ಮತ್ತು ಚೆಲ್ಲುವ ಪದ್ಧತಿಗೆ ಹೆಕ್ಟೇರಿಗೆ 10 ಕೆಜಿ (ಎಕರೆಗೆ 4 ರಿಂದ 5 ಕೆಜಿ) ಬೀಜ ಬೇಕು."),
        ("VKB-098", "transplanting_vs_direct", "ತರಕಾರಿಗಳಲ್ಲಿ ನೇರ ಬಿತ್ತನೆಗಿಂತ ಸಸಿ ನಾಟಿ ಮಾಡುವುದು ಉತ್ತಮವೇ?", ["ಸಸಿ ನಾಟಿ", "ನೇರ ಬಿತ್ತನೆ", "ಪ್ರೋಟ್ರೆ"], "ಟೊಮೆಟೊ, ಬದನೆ, ಮೆಣಸಿನಕಾಯಿ, ಈರುಳ್ಳಿ ಬೆಳೆಗಳಿಗೆ ಪ್ರೋಟ್ರೆಗಳಲ್ಲಿ ಸಸಿ ಮಡಿ ತಯಾರಿಸಿ 25-30 ದಿನದ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದರಿಂದ 95% ಮೊಳಕೆ ಉಳಿದು ಏಕರೂಪ ಬೆಳವಣಿಗೆಯಾಗುತ್ತದೆ."),
        ("VKB-099", "seed_dormancy", "ಬೀಜದ ಸುಪ್ತಾವಸ್ಥೆ (Dormancy) ಮುರಿಯುವುದು ಹೇಗೆ?", ["ಸುಪ್ತಾವಸ್ಥೆ", "ಬೀಜ ಸುಪ್ತತೆ", "ಡಾರ್ಮೆನ್ಸಿ"], "ತಾಜಾ ಕೊಯ್ಲಿನ ಭತ್ತ ಮತ್ತು ಶೇಂಗಾ ಬೀಜಗಳಲ್ಲಿ ಸುಪ್ತಾವಸ್ಥೆ ಇದ್ದರೆ 1 ಲೀಟರ್ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಪೊಟ್ಯಾಶಿಯಂ ನೈಟ್ರೇಟ್ (KNO3) ಅಥವಾ ಎಥ್ರೆಲ್ ಬೆರೆಸಿ ಬೀಜ ನೆನೆಸಿ ಒಣಗಿಸಿ ಬಿತ್ತಬೇಕು."),
        ("VKB-100", "crop_rotation", "ಬೆಳೆ ಪರಿವರ್ತನೆ (Crop Rotation) ಮಾಡುವುದರಿಂದ ಏನು ಪ್ರಯೋಜನ?", ["ಬೆಳೆ ಪರಿವರ್ತನೆ", "ಕ್ರಾಪ್ ರೊಟೇಷನ್", "ಮಣ್ಣಿನ ಸಾರ"], "ಒಂದೇ ಜಮೀನಿನಲ್ಲಿ ಸತತವಾಗಿ ಒಂದೇ ಬೆಳೆ ಬೆಳೆಯದೆ ಏಕದಳ ಧಾನ್ಯದ ನಂತರ ದ್ವಿದಳ ಧಾನ್ಯ (ತೊಗರಿ/ಕಡಲೆ) ಬೆಳೆದರೆ ರೋಗ-ಕೀಟಗಳ ಜೀವನಚಕ್ರ ತುಂಡಾಗುತ್ತದೆ ಮತ್ತು ಮಣ್ಣಿನ ಫಲವತ್ತತೆ ಹೆಚ್ಚುತ್ತದೆ."),
        ("VKB-101", "ragi_sowing_seed", "ರಾಗಿ ಬಿತ್ತನೆಗೆ ಯಾವ ತಳಿ ಉತ್ತಮ ಮತ್ತು ಬೀಜ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ರಾಗಿ ತಳಿ", "ಎಂಎಲ್-365", "ಜಿಪಿಯು-28", "ಬೀಜ ಪ್ರಮಾಣ"], "ತಳಿಗಳು: ಎಂಎಲ್-365 (ಬರ ನಿರೋಧಕ), ಜಿಪಿಯು-28 (ರೋಗ ಮುಕ್ತ). ಸಾಲು ಬಿತ್ತನೆಗೆ ಎಕರೆಗೆ 2 ರಿಂದ 2.5 ಕೆಜಿ ಬೀಜ ಸಾಕು. ಅಂತರ: ಸಾಲಿನ ನಡುವೆ 1 ಅಡಿ, ಸಸಿ ನಡುವೆ 10 ಸೆಂ.ಮೀ."),
        ("VKB-102", "germination_test", "ಮನೆಯಲ್ಲೇ ಬೀಜ ಮೊಳಕೆ ಪರೀಕ್ಷೆ ಮಾಡುವುದು ಹೇಗೆ?", ["ಮೊಳಕೆ ಪರೀಕ್ಷೆ", "ಗೋಣಿಚೀಲ", "ಶೇಕಡಾವಾರು"], "ಒದ್ದೆ ಗೋಣಿಚೀಲದ ಮೇಲೆ 100 ಬೀಜ ಇಟ್ಟು 4 ದಿನ ತೇವಾಂಶದಲ್ಲಿಡಿ. 85 ಕ್ಕೂ ಹೆಚ್ಚು ಬೀಜ ಮೊಳಕೆಯೊಡೆದರೆ ಮಾತ್ರ ಬಿತ್ತನೆಗೆ ಯೋಗ್ಯ."),
        ("VKB-103", "fir_treatment", "ಬೀಜೋಪಚಾರದ ಎಫ್.ಐ.ಆರ್ (FIR) ಕ್ರಮ ಯಾವುದು?", ["ಬೀಜೋಪಚಾರ", "ಎಫ್‌ಐಆರ್", "ಶಿಲೀಂಧ್ರನಾಶಕ", "ರೈಜೋಬಿಯಂ"], "ಕ್ರಮವಾಗಿ: 1. F (Fungicide - ಶಿಲೀಂಧ್ರನಾಶಕ). 2. I (Insecticide - ಕೀಟನಾಶಕ). 3. R (Rhizobium - ಜೈವಿಕ ಗೊಬ್ಬರ ಕೊನೆಗೆ ಬೆಲ್ಲದ ನೀರಿನೊಂದಿಗೆ ಲೇಪಿಸಿ)."),
        ("VKB-104", "tomato_spacing", "ಟೊಮೆಟೊ ಸಸಿ ನಾಟಿ ಮಾಡುವ ಅಂತರ ಎಷ್ಟು?", ["ಟೊಮೆಟೊ", "ನಾಟಿ", "ಅಂತರ", "ಸಸಿ ಮಡಿ"], "ಬೆಡ್‌ಗಳ ನಡುವೆ 3 ರಿಂದ 4 ಅಡಿ ಮತ್ತು ಸಸಿಗಳ ನಡುವೆ 1.5 ರಿಂದ 2 ಅಡಿ ಅಂತರವಿರಬೇಕು. 25 ದಿನದ ಗಟ್ಟಿ ಸಸಿಗಳನ್ನು ಸಂಜೆ ಹೊತ್ತು ನಾಟಿ ಮಾಡಿ."),
        ("VKB-105", "ragi_pulses_intercrop", "ರಾಗಿ ಜೊತೆ ತೊಗರಿ ಅಂತರ ಬೆಳೆ ಸಾಲುಗಳ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ಮಿಶ್ರ ಬೆಳೆ", "ಅಂತರ ಬೆಳೆ", "ರಾಗಿ", "ತೊಗರಿ"], "8:2 ಅಥವಾ 10:2 ಸಾಲುಗಳ ಪ್ರಮಾಣ. 8 ಸಾಲು ರಾಗಿಗೆ 2 ಸಾಲು ತೊಗರಿ ಅಥವಾ ಅವರೆ ಬಿತ್ತನೆ ಮಾಡಬೇಕು."),
        ("VKB-106", "maize_varieties", "ಮೆಕ್ಕೆಜೋಳದ ಅಧಿಕ ಇಳುವರಿ ಹೈಬ್ರಿಡ್ ತಳಿಗಳು ಯಾವುವು?", ["ಮೆಕ್ಕೆಜೋಳ", "ಹೈಬ್ರಿಡ್ ತಳಿ", "ಸಿಪಿ-818", "ಕಾರ್ಗಿಲ್"], "ಸಿಪಿ-818, ಕಾರ್ಗಿಲ್ 900M, ಎನ್‌ಕೆ-6240 ಮತ್ತು ಡೆಕಾಲ್ಬ್-9108. 1 ಎಕರೆಗೆ 7-8 ಕೆಜಿ ಬೀಜ ಬೇಕು. ಅಂತರ: 60 x 20 ಸೆಂ.ಮೀ."),
        ("VKB-107", "groundnut_varieties", "ಶೇಂಗಾ ಬಿತ್ತನೆಗೆ ಯಾವ ತಳಿಗಳು ಉತ್ತಮ?", ["ಶೇಂಗಾ ತಳಿ", "ಟಿಎಂವಿ-2", "ಜೆಎಲ್-24", "ಕೆಡಿಜಿ-128"], "ಟಿಎಂವಿ-2, ಜೆಎಲ್-24, ಜಿಪಿಬಿಡಿ-4 (ರೋಗ ನಿರೋಧಕ) ಮತ್ತು ಕೆಡಿಜಿ-128. ಎಕರೆಗೆ 40-45 ಕೆಜಿ ಬೀಜ ಬೇಕು."),
        ("VKB-108", "tur_varieties", "ತೊಗರಿ ಬೆಳೆಯ ಉತ್ತಮ ತಳಿಗಳು ಯಾವುವು?", ["ತೊಗರಿ ತಳಿ", "ಬಿಆರ್‌ಜಿ-1", "ಜಿಆರ್‌ಜಿ-152", "ಆಶಾ"], "ಜಿಆರ್‌ಜಿ-152, ಬಿಆರ್‌ಜಿ-1, ಬಿಆರ್‌ಜಿ-2 ಮತ್ತು ಆಶಾ (ICPL-87119). ಎಕರೆಗೆ 4-5 ಕೆಜಿ ಬೀಜ ಸಾಕು."),
        ("VKB-109", "paddy_varieties", "ಕರ್ನಾಟಕದಲ್ಲಿ ಸೋನಾ ಮಸೂರಿ ಮತ್ತು ಇತರ ಉತ್ತಮ ಭತ್ತದ ತಳಿಗಳು ಯಾವುವು?", ["ಭತ್ತದ ತಳಿ", "ಸೋನಾ ಮಸೂರಿ", "ಬಿಪಿಟಿ-5204", "ಗಂಗಾವತಿ"], "ಬಿಪಿಟಿ-5204 (ಸೋನಾ ಮಸೂರಿ), ಜಯ, ಐಇಟಿ-1444 ಮತ್ತು ತುಂಗಾ. ಎಕರೆಗೆ 20-25 ಕೆಜಿ ಬೀಜ ಸಸಿ ಮಡಿಗೆ ಬೇಕು."),
        ("VKB-110", "cotton_bt_spacing", "ಬಿಟಿ ಹತ್ತಿ ಬಿತ್ತನೆ ಸಾಲಿನ ಅಂತರ ಎಷ್ಟು ಇರಬೇಕು?", ["ಹತ್ತಿ ಬಿತ್ತನೆ", "ಬಿಟಿ ಹತ್ತಿ", "ಅಂತರ"], "ಸಾಲಿನಿಂದ ಸಾಲಿಗೆ 3 ರಿಂದ 4 ಅಡಿ ಮತ್ತು ಗಿಡಗಳ ನಡುವೆ 2 ರಿಂದ 3 ಅಡಿ ಅಂತರವಿರಬೇಕು. ಎಕರೆಗೆ 1 ರಿಂದ 2 ಪ್ಯಾಕೆಟ್ ಬೀಜ ಸಾಕು."),
        ("VKB-111", "onion_bbf", "ಈರುಳ್ಳಿ ಬೀಜ ಬಿತ್ತನೆ ಅಥವಾ ಗಡ್ಡೆ ನಾಟಿ ಮಾಡಲು ಬೋದು ಸಾಲು (BBF) ಉತ್ತಮವೇ?", ["ಈರುಳ್ಳಿ ನಾಟಿ", "ಬೋದು ಸಾಲು", "BBF", "ಅಂತರ"], "ಹೌದು, ಬ್ರಾಡ್ ಬೆಡ್ ಫರ್ರೋ (BBF) ಪದ್ಧತಿಯಲ್ಲಿ 4 ಅಡಿ ಅಗಲದ ಬೆಡ್ ಮಾಡಿ 10 ಸೆಂ.ಮೀ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡಿದರೆ ನೀರು ನಿಲ್ಲದೆ ಗೆಡ್ಡೆಗಳು ದಪ್ಪವಾಗಿ ಬೆಳೆಯುತ್ತವೆ."),
        ("VKB-112", "kharif_sowing_time", "ಕರ್ನಾಟಕದಲ್ಲಿ ಮುಂಗಾರು (ಖಾರಿಫ್) ಬಿತ್ತನೆಗೆ ಸೂಕ್ತ ಸಮಯ ಯಾವುದು?", ["ಮುಂಗಾರು ಬಿತ್ತನೆ", "ಖಾರಿಫ್", "ಜೂನ್", "ಜುಲೈ"], "ಜೂನ್ ಮೊದಲ ವಾರದಿಂದ ಜುಲೈ 15 ರವರೆಗೆ ಮುಂಗಾರು ಬಿತ್ತನೆಗೆ ಸಕಾಲ. 75 ಮಿ.ಮೀ ಗಿಂತ ಹೆಚ್ಚು ಮಳೆಯಾಗಿ ಮಣ್ಣು ಹದವಾದಾಗ ಬಿತ್ತನೆ ಮಾಡಬೇಕು."),
        ("VKB-113", "rabi_sowing_time", "ಹಿಂಗಾರು (ರಬಿ) ಕಡಲೆ ಮತ್ತು ಜೋಳ ಬಿತ್ತನೆ ಯಾವಾಗ ಮಾಡಬೇಕು?", ["ಹಿಂಗಾರು ಬಿತ್ತನೆ", "ರಬಿ", "ಕಡಲೆ", "ಅಕ್ಟೋಬರ್"], "ಸೆಪ್ಟೆಂಬರ್ 15 ರಿಂದ ಅಕ್ಟೋಬರ್ ಅಂತ್ಯದವರೆಗೆ ಹಿಂಗಾರು ಕಡಲೆ, ಕುಸುಬೆ ಮತ್ತು ರಬಿ ಜೋಳ ಬಿತ್ತನೆಗೆ ಸೂಕ್ತ ಸಮಯ."),
        ("VKB-114", "certified_seeds", "ಪ್ರಮಾಣೀಕೃತ ಬೀಜ (Certified seed) ಮತ್ತು ರೈತರ ಮನೆ ಬೀಜದ ವ್ಯತ್ಯಾಸವೇನು?", ["ಪ್ರಮಾಣೀಕೃತ ಬೀಜ", "ಬ್ಲೂ ಟ್ಯಾಗ್", "ಮೊಳಕೆ ಶೇಕಡಾ"], "ಪ್ರಮಾಣೀಕೃತ ಬೀಜವು ಕೃಷಿ ಇಲಾಖೆಯಿಂದ ಪ್ರಮಾಣೀಕರಿಸಲ್ಪಟ್ಟು (ನೀಲಿ ಟ್ಯಾಗ್) ಕನಿಷ್ಠ 98% ಶುದ್ಧತೆ ಮತ್ತು 85% ಮೊಳಕೆ ಖಾತ್ರಿ ಹೊಂದಿರುತ್ತದೆ. ರೋಗ ಮುಕ್ತವಾಗಿರುತ್ತದೆ."),
        ("VKB-115", "seed_soaking", "ಬಿತ್ತನೆಗೆ ಮುನ್ನ ಬೀಜಗಳನ್ನು ನೀರಿನಲ್ಲಿ ನೆನೆಸಿ ಬಿತ್ತಬಹುದೇ?", ["ಬೀಜ ನೆನೆಸುವುದು", "ಮೊಳಕೆ", "ಮೆಕ್ಕೆಜೋಳ"], "ಮೆಕ್ಕೆಜೋಳ, ಹತ್ತಿ ಮತ್ತು ರಾಗಿ ಬೀಜಗಳನ್ನು ಬಿತ್ತನೆಗೆ 6-8 ಗಂಟೆ ಮುಂಚೆ ನೀರಿನಲ್ಲಿ ನೆನೆಸಿ ನೆರಳಿನಲ್ಲಿ ಒಣಗಿಸಿ ಬಿತ್ತಿದರೆ 2 ದಿನ ಮುಂಚಿತವಾಗಿ ಸಮಾನವಾಗಿ ಮೊಳಕೆಯೊಡೆಯುತ್ತವೆ."),
        ("VKB-116", "ginger_planting", "ಶುಂಠಿ ನಾಟಿ ಮಾಡಲು ಸೂಕ್ತ ತಿಂಗಳು ಮತ್ತು ಗಡ್ಡೆ ಪ್ರಮಾಣ ಎಷ್ಟು?", ["ಶುಂಠಿ ನಾಟಿ", "ಏಪ್ರಿಲ್", "ಮೇ", "ಕ್ವಿಂಟಾಲ್"], "ಏಪ್ರಿಲ್ ಎರಡನೇ ವಾರದಿಂದ ಮೇ ಅಂತ್ಯದವರೆಗೆ ಶುಂಠಿ ನಾಟಿಗೆ ಸಕಾಲ. 1 ಎಕರೆಗೆ 8 ರಿಂದ 10 ಕ್ವಿಂಟಾಲ್ ಆರೋಗ್ಯವಂತ ಬೀಜದ ಗಡ್ಡೆ ಬೇಕಾಗುತ್ತದೆ."),
        ("VKB-117", "arecanut_planting", "ಅಡಿಕೆ ಸಸಿ ನಾಟಿ ಮಾಡಲು ಗುಂಡಿಯ ಅಳತೆ ಮತ್ತು ಅಂತರ ಎಷ್ಟು?", ["ಅಡಿಕೆ ನಾಟಿ", "ಅಂತರ", "ಗುಂಡಿ ಅಳತೆ"], "ಗಿಡದಿಂದ ಗಿಡಕ್ಕೆ 9 x 9 ಅಡಿ ಅಂತರ. 3x3x3 ಅಡಿ ಗುಂಡಿ ತೆಗೆದು ಮೇಲ್ಮಣ್ಣು, 20 ಕೆಜಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು 2 ಕೆಜಿ ಬೇವಿನ ಹಿಂಡಿ ತುಂಬಿ 1-2 ವರ್ಷದ ಸಸಿ ನೆಡಬೇಕು."),
        ("VKB-118", "banana_tissue_culture", "ಬಾಳೆ ಕಂದು ನೆಡುವುದಕ್ಕಿಂತ ಟಿಶ್ಯೂ ಕಲ್ಚರ್ ಸಸಿ ನೆಡುವುದು ಉತ್ತಮವೇ?", ["ಟಿಶ್ಯೂ ಕಲ್ಚರ್", "ಬಾಳೆ ಸಸಿ", "ಜಿ9", "ಇಳುವರಿ"], "ಹೌದು, ಟಿಶ್ಯೂ ಕಲ್ಚರ್ (ಜಿ-9) ಸಸಿಗಳು ರೋಗ ಮುಕ್ತವಾಗಿರುತ್ತವೆ, ಎಲ್ಲ ಗಿಡಗಳು ಒಂದೇ ಸಮಯದಲ್ಲಿ ಕೊಯ್ಲಿಗೆ ಬರುತ್ತವೆ ಮತ್ತು 20-30% ಹೆಚ್ಚಿನ ಇಳುವರಿ ನೀಡುತ್ತವೆ."),
        ("VKB-119", "chilli_seedling_age", "ಮೆಣಸಿನಕಾಯಿ ಸಸಿಗಳನ್ನು ಎಷ್ಟು ದಿನಕ್ಕೆ ನಾಟಿ ಮಾಡಬೇಕು?", ["ಮೆಣಸಿನಕಾಯಿ ನಾಟಿ", "ಸಸಿ ವಯಸ್ಸು", "ಪ್ರೋಟ್ರೆ"], "ಸಸಿ ಮಡಿಯಲ್ಲಿ ಅಥವಾ ಪ್ರೋಟ್ರೆಗಳಲ್ಲಿ ಬೆಳೆದ 30 ರಿಂದ 35 ದಿನದ (4-5 ಎಲೆಗಳಿರುವ) ಆರೋಗ್ಯವಂತ ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಬೇಕು."),
        ("VKB-120", "fodder_grass_slips", "ನೇಪಿಯರ್ ಹಸಿರು ಮೇವಿನ ಕಂದುಗಳನ್ನು ಹೇಗೆ ನೆಡಬೇಕು?", ["ಮೇವು ಕಂದು", "ನೇಪಿಯರ್", "ಅಂತರ"], "3 x 2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಚಾನಲ್ ಮಾಡಿ 45 ಡಿಗ್ರಿ ಕೋನದಲ್ಲಿ 2 ಗಣ್ಣಿನ ಕಂದುಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಒಂದು ಗಣ್ಣು ಮುಳುಗುವಂತೆ ನೆಡಬೇಕು.")
    ]

